#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_new_with_string_length_basic_success(void) {
    // Setup: create a string and specify a length
    char test_str[] = "hello world";
    size_t test_len = 5; // Only use "hello"

    // Test: call the function under test
    buffer_t *buf = buffer_new_with_string_length(test_str, test_len);

    // Assertions
    TEST_ASSERT_NOT_NULL(buf);
    TEST_ASSERT_EQUAL(test_len, buf->len);
    TEST_ASSERT_EQUAL_PTR(test_str, buf->data);
    TEST_ASSERT_EQUAL_PTR(test_str, buf->alloc);

    // The buffer's data should match the first 'test_len' bytes of test_str
    helper_assert_buffer_data_equals(buf, test_str, test_len);

    // Cleanup: only free the buffer, not test_str (ownership retained by caller)
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_new_with_string_length_basic_success);
    return UNITY_END();
}


